struct Token { int glyph; size_t consumed; };

inline constexpr Token decode(const char* p) {
    if (!p || !*p)
        return {-1, 0};

    if (p[0] != '\\')
        return {ordinaryIndex(p[0]), 1};

    // p[1] is safe here: p[0] is a non-null character.
    if (p[1] == '\0')
        return {-1, 1};

    if (p[1] == '\\')
        return {backslashGlyph, 2};

    if (p[1] == '{') {
        size_t i = 2;
        unsigned value = 0;
        bool digit = false;
        bool good = true;

        // Never advance past the null terminator.
        while (p[i] != '\0' &&
               p[i] >= '0' && p[i] <= '9') {
            digit = true;
            const unsigned d = unsigned(p[i] - '0');

            if (value > 6553u || (value == 6553u && d > 5u))
                good = false;

            if (good)
                value = value * 10u + d;

            ++i;
        }

        // Only inspect the next character if it exists.
        if (digit && p[i] == '}' &&
            p[i + 1] != '\0' &&
            p[i + 1] == '\\') {
            return {
                good && value < specialCount
                    ? int(symbolCount + value)
                    : -1,
                i + 2
            };
        }
    }

    return {-1, 1};
}

// Callback signature: setPixel(int x, int y, bool on). Calls only for ON pixels.
template <class SetPixel>
constexpr int drawText(const char* text, int x, int y, SetPixel setPixel,
                    RenderMode mode=RenderMode::Proportional) {
  if (!text) return 0;
  const int start=x;
  while (*text) {
    const Token t=decode(text); if(!t.consumed) break; text+=t.consumed;
    const bool valid=t.glyph>=0 && t.glyph<int(symbolCount+specialCount);
    const int w=valid?widths[t.glyph]:3;
    const int cell=6;
    const int shift=mode==RenderMode::Fixed && cell>w ? (cell-w)/2 : 0;
    if(valid) for(int col=0;col<w;++col) {
      if(mode==RenderMode::Fixed && col+shift>=cell) break;
      const uint8_t bits=bitmap[offsets[t.glyph]+col];
      for(int row=0;row<8;++row)
        if(bits & (uint8_t(1)<<row)) setPixel(x+shift+col,y+row,true);
    }
    x+=mode==RenderMode::Fixed?cell:w+1;
  }
  return x-start;
}
